import { useEffect, useRef, useState } from "react";

const AboutUs = () => {
  const [scrollY, setScrollY] = useState(0);
  const [visibleSections, setVisibleSections] = useState({});
  const sectionRefs = useRef({});

  useEffect(() => {
    const handleScroll = () => setScrollY(window.scrollY);
    window.addEventListener("scroll", handleScroll);
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            setVisibleSections((prev) => ({ ...prev, [entry.target.id]: true }));
          }
        });
      },
      { threshold: 0.15 }
    );
    Object.values(sectionRefs.current).forEach((ref) => {
      if (ref) observer.observe(ref);
    });
    return () => observer.disconnect();
  }, []);

  const setRef = (id) => (el) => {
    sectionRefs.current[id] = el;
  };

  const isVisible = (id) => visibleSections[id];

  const features = [
    { icon: "⚡", title: "Instant Generation", desc: "From idea to polished content in seconds using Groq's blazing-fast AI." },
    { icon: "🎯", title: "Platform-Aware", desc: "Tailored for Instagram, Twitter, LinkedIn, YouTube — every platform's vibe." },
    { icon: "🏆", title: "Community Canvas", desc: "Share your creations, rise through ranks, gift stars to fellow creators." },
    { icon: "🇮🇳", title: "Built for India", desc: "₹299 plans, Tamil & Hindi support, no VPN tricks — made for us, by us." },
  ];

  const team = [
    { name: "Kaasish", role: "Founder & Builder", emoji: "👑", desc: "Who got tired of staring at blank screens." },
    { name: "Nikitha", role: "Co-Founder & Idea Planner", emoji: "🤝", desc: "Who asked 'what do I even post?' — and sparked this entire idea." },
    { name: "You", role: "The Community", emoji: "🌟", desc: "Every creator who joins The Canvas makes ContentAI what it is." },
  ];

  return (
    <div style={styles.root}>
      {/* Noise overlay */}
      <div style={styles.noiseOverlay} />

      {/* Floating orbs */}
      <div style={{ ...styles.orb, ...styles.orb1, opacity: Math.max(0, 1 - scrollY / 600) }} />
      <div style={{ ...styles.orb, ...styles.orb2, opacity: Math.max(0, 1 - scrollY / 800) }} />
      <div style={{ ...styles.orb, ...styles.orb3 }} />

      {/* Nav */}
      <nav style={styles.nav}>
        <div style={styles.navLogo}>
          <span style={styles.navLogoIcon}>✦</span>
          <span style={styles.navLogoText}>ContentAI</span>
        </div>
        <a href="/login" style={styles.navCta}>Get Started →</a>
      </nav>

      {/* HERO */}
      <section style={styles.hero}>
        <div style={styles.heroBadge}>
          <span style={styles.heroBadgeDot} />
          Our Story
        </div>
        <h1 style={styles.heroTitle}>
          We were confused.<br />
          <span style={styles.heroTitleAccent}>So we built this.</span>
        </h1>
        <p style={styles.heroSub}>
          ContentAI started from a real problem — not a boardroom. We tried to solve a real world problem, 
          staring at their phones, wondering what to post next. Sound familiar?
        </p>
        <div style={styles.heroScroll}>
          <div style={styles.heroScrollLine} />
          <span style={styles.heroScrollText}>scroll</span>
        </div>
      </section>

      {/* STORY */}
      <section
        id="story"
        ref={setRef("story")}
        style={{
          ...styles.section,
          ...styles.storySection,
          opacity: isVisible("story") ? 1 : 0,
          transform: isVisible("story") ? "translateY(0)" : "translateY(40px)",
          transition: "all 0.8s cubic-bezier(0.16, 1, 0.3, 1)",
        }}
      >
        <div style={styles.storyGrid}>
          <div style={styles.storyLeft}>
            <div style={styles.storyTag}>The Origin</div>
            <h2 style={styles.storyTitle}>It started with a group chat.</h2>
          </div>
          <div style={styles.storyRight}>
            <div style={styles.storyCard}>
              <div style={styles.storyCardIcon}>💬</div>
              <p style={styles.storyCardText}>
                "Guys what should I post today?"
              </p>
              <p style={styles.storyCardSub}>— every group chat, every day</p>
            </div>
            <p style={styles.storyPara}>
              Me and my friends kept hitting the same wall. We had ideas, we had things to say — 
              but turning that into actual content for Instagram, LinkedIn, Twitter? That part was painful. 
              We'd spend more time on the caption than on the actual thought.
            </p>
            <p style={styles.storyPara}>
              No fancy startup origin. No investors. Just me and my teammate who got annoyed 
              enough to build something. ContentAI was born from that exact frustration — 
              and every feature exists because we needed it ourselves.
            </p>
            <div style={styles.storyHighlight}>
              <span style={styles.storyHighlightText}>
                "Built by creators who were stuck, for creators who are stuck."
              </span>
            </div>
          </div>
        </div>
      </section>

      {/* MISSION */}
      <section
        id="mission"
        ref={setRef("mission")}
        style={{
          ...styles.section,
          ...styles.missionSection,
          opacity: isVisible("mission") ? 1 : 0,
          transform: isVisible("mission") ? "translateY(0)" : "translateY(40px)",
          transition: "all 0.8s cubic-bezier(0.16, 1, 0.3, 1) 0.1s",
        }}
      >
        <div style={styles.missionInner}>
          <div style={styles.missionLabel}>Our Mission</div>
          <h2 style={styles.missionTitle}>
            Every creator deserves a<br />
            <span style={styles.missionAccent}>voice that doesn't get stuck.</span>
          </h2>
          <p style={styles.missionDesc}>
            We're not here to replace your creativity. We're here to unblock it. 
            ContentAI is the co-pilot that turns your raw thoughts into content 
            that actually sounds like you — just faster.
          </p>
          <div style={styles.missionStats}>
            {[
              { num: "5+", label: "Platforms Supported" },
              { num: "₹299", label: "Unlimited Plan" },
              { num: "∞", label: "Ideas Unlocked" },
            ].map((stat) => (
              <div key={stat.label} style={styles.missionStat}>
                <div style={styles.missionStatNum}>{stat.num}</div>
                <div style={styles.missionStatLabel}>{stat.label}</div>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* WHAT MAKES US DIFFERENT */}
      <section
        id="different"
        ref={setRef("different")}
        style={{
          ...styles.section,
          opacity: isVisible("different") ? 1 : 0,
          transform: isVisible("different") ? "translateY(0)" : "translateY(40px)",
          transition: "all 0.8s cubic-bezier(0.16, 1, 0.3, 1)",
        }}
      >
        <div style={styles.sectionHeader}>
          <div style={styles.sectionTag}>Why ContentAI</div>
          <h2 style={styles.sectionTitle}>Not just another AI tool.</h2>
        </div>
        <div style={styles.featuresGrid}>
          {features.map((f, i) => (
            <div
              key={f.title}
              style={{
                ...styles.featureCard,
                opacity: isVisible("different") ? 1 : 0,
                transform: isVisible("different") ? "translateY(0)" : "translateY(30px)",
                transition: `all 0.6s cubic-bezier(0.16, 1, 0.3, 1) ${i * 0.1 + 0.2}s`,
              }}
            >
              <div style={styles.featureIcon}>{f.icon}</div>
              <h3 style={styles.featureTitle}>{f.title}</h3>
              <p style={styles.featureDesc}>{f.desc}</p>
            </div>
          ))}
        </div>
      </section>

      {/* TEAM */}
      <section
        id="team"
        ref={setRef("team")}
        style={{
          ...styles.section,
          opacity: isVisible("team") ? 1 : 0,
          transform: isVisible("team") ? "translateY(0)" : "translateY(40px)",
          transition: "all 0.8s cubic-bezier(0.16, 1, 0.3, 1)",
        }}
      >
        <div style={styles.sectionHeader}>
          <div style={styles.sectionTag}>The People</div>
          <h2 style={styles.sectionTitle}>Who's behind this?</h2>
        </div>
        <div style={styles.teamGrid}>
          {team.map((member, i) => (
            <div
              key={member.name}
              style={{
                ...styles.teamCard,
                ...(i === 0 ? styles.teamCardFeatured : {}),
                opacity: isVisible("team") ? 1 : 0,
                transform: isVisible("team") ? "translateY(0) rotate(0deg)" : "translateY(30px) rotate(2deg)",
                transition: `all 0.7s cubic-bezier(0.16, 1, 0.3, 1) ${i * 0.15}s`,
              }}
            >
              <div style={styles.teamEmoji}>{member.emoji}</div>
              <h3 style={styles.teamName}>{member.name}</h3>
              <div style={styles.teamRole}>{member.role}</div>
              <p style={styles.teamDesc}>{member.desc}</p>
            </div>
          ))}
        </div>
      </section>

      {/* CTA */}
      <section
        id="cta"
        ref={setRef("cta")}
        style={{
          ...styles.ctaSection,
          opacity: isVisible("cta") ? 1 : 0,
          transform: isVisible("cta") ? "scale(1)" : "scale(0.96)",
          transition: "all 0.8s cubic-bezier(0.16, 1, 0.3, 1)",
        }}
      >
        <div style={styles.ctaInner}>
          <div style={styles.ctaGlow} />
          <p style={styles.ctaEyebrow}>Ready to create?</p>
          <h2 style={styles.ctaTitle}>Stop staring.<br />Start creating.</h2>
          <p style={styles.ctaDesc}>
            Join creators who stopped struggling with blank screens.
            It's free to start — no credit card needed.
          </p>
          <div style={styles.ctaButtons}>
            <span onClick={onGetStarted} style={{...styles.ctaPrimary, cursor: "pointer"}}>Start for Free</span>
            <a href="/login" style={styles.ctaSecondary}>See Pricing</a>
          </div>
          <p style={styles.ctaNote}>✦ Free plan includes 5 generations/day</p>
        </div>
      </section>

      {/* FOOTER */}
      <footer style={styles.footer}>
        <div style={styles.footerLogo}>
          <span style={styles.navLogoIcon}>✦</span>
          <span style={styles.navLogoText}>ContentAI</span>
        </div>
        <p style={styles.footerTagline}>Made with frustration & love in Madurai 🇮🇳</p>
        <div style={styles.footerLinks}>
          <a href="/login" style={styles.footerLink}>App</a>
          <a href="#" style={styles.footerLink}>Privacy</a>
          <a href="#" style={styles.footerLink}>Terms</a>
        </div>
        <p style={styles.footerCopy}>© 2025 ContentAI. All rights reserved.</p>
      </footer>
    </div>
  );
};

